INSERT INTO `remote_commands` VALUES (2,'app.repc',9,1,60,0,'linux','RUBYLIB=/opt/Jigsaw/Library/ruby timeout 10 /opt/local/bin/ruby /opt/Jigsaw/Library/ruby/rjams.rb -c -d host 2>/dev/null','fms','bash',30,1,NULL,'2026-01-28 03:41:31','insert_always'),(3,'app.fms.active_scripts',8,1,30,0,'linux','ps -eo pid,user,etime,command | grep -E \'/opt/Jigsaw/Clients/.*.(rb|sh)\' | grep -v grep || true','fms','bash',30,1,NULL,'2026-01-28 03:41:31','insert_always'),(4,'app.fms.version',7,1,30,0,'linux','head -n 1 /opt/Jigsaw/Versions/JAMS','fms','bash',300,1,NULL,'2026-01-28 03:41:31','insert_always'),(5,'app.jams.version',28,1,30,0,'linux','head -n 1 /opt/Jigsaw/Versions/JAMS','fms','bash',300,1,NULL,'2026-01-28 03:41:31','insert_always'),(6,'app.station.ping',10,1,30,0,'linux','ipEB=$(cat /opt/Jigsaw/Services/config.jams | grep -Ei \'rtcm3ext\' | awk -F\'port=\' \'{print $2}\' | awk -F\'[;\\\\], ]\' \'{print $1}\' | cut -d\':\' -f1); if [[ \"$ipEB\" =~ ^[0-9]+\\.[0-9]+\\.[0-9]+\\.[0-9]+$ ]]; then ping -c 3 \"$ipEB\" | tail -3; else echo \"Non-IP port: $ipEB\"; fi','fms','bash',60,1,NULL,'2026-01-28 03:41:31','check_then_insert'),(7,'backup.daily.status',16,1,30,0,'linux','file=$(find /opt/Jigsaw/Backups/daily -maxdepth 1 -type f -name \'*.t*gz\' -printf \'%T@ %p\\n\' 2>/dev/null | sort -nr | head -n1 | cut -d\' \' -f2-); if [ ! -z \"$file\" ]; then secs=$(( $(date +%s) - $(stat -c %Y \"$file\") )); printf \"%s %d-%02d:%02d:%02d\\n\" \"$(basename \"$file\")\" $((secs/86400)) $((secs%86400/3600)) $((secs%3600/60)) $((secs%60)); else echo \"No backup\"; fi','fms','bash',600,1,NULL,'2026-01-28 03:41:31','update_only'),(8,'backup.hourly.status',18,1,30,0,'linux','file=$(find /opt/Jigsaw/Backups/hourly -maxdepth 1 -type f -name \'*.t*gz\' -printf \'%T@ %p\\n\' 2>/dev/null | sort -nr | head -n1 | cut -d\' \' -f2-); if [ ! -z \"$file\" ]; then secs=$(( $(date +%s) - $(stat -c %Y \"$file\") )); printf \"%s %d-%02d:%02d:%02d\\n\" \"$(basename \"$file\")\" $((secs/86400)) $((secs%86400/3600)) $((secs%3600/60)) $((secs%60)); else echo \"No backup\"; fi','fms','bash',600,1,NULL,'2026-01-28 03:41:31','update_only'),(9,'db.integrity.diff',13,1,30,0,'linux','SELECT \'shift_dumps\', count(*) FROM shift_dumps UNION ALL SELECT \'shift_loads\', count(*) FROM shift_loads UNION ALL SELECT \'shift_hauls\', count(*) FROM shift_hauls UNION ALL SELECT \'shift_states\', count(*) FROM shift_states','fms','psql',600,1,NULL,'2026-01-28 03:41:31','insert_always'),(10,'db.integrity.tables',12,1,30,0,'linux','cmd=\"SELECT \'SELECT * FROM (\' || string_agg(\'SELECT \' || quote_literal(table_name) || \' AS table_name, max(id) AS max_id FROM \' || quote_ident(table_name), \' UNION ALL \') || \') AS final WHERE max_id IS NOT NULL ORDER BY max_id DESC LIMIT 10;\' FROM (SELECT DISTINCT table_name FROM information_schema.columns c JOIN pg_tables t ON c.table_name = t.tablename AND c.table_schema = t.schemaname WHERE c.column_name = \'id\' AND c.table_schema = \'public\') s;\"; psql -U {db_user} -d {db_name} -t -A -c \"$cmd\" | psql -U {db_user} -d {db_name} -t -A -F\'|\' -f -','fms','bash',60,0,NULL,'2026-01-28 03:41:31','insert_always'),(11,'db.schema.date',11,1,30,0,'linux','select to_local(backup_at) from schema_info;','fms','psql',180,1,NULL,'2026-01-28 03:41:31','update_only'),(12,'db.size',14,1,30,0,'linux','SELECT pg_size_pretty(pg_database_size(current_database()))','fms','psql',43200,1,NULL,'2026-01-28 03:41:31','insert_always'),(13,'app.jams.service',19,1,30,0,'linux','ps aux | grep JAMS','fms','bash',30,1,NULL,'2026-01-28 03:41:31','check_then_insert'),(20,'system.cpu.load',1,1,4,0,'linux','uptime | awk -F\'load average: \' \'{split($2, a, \",\"); print a[1]}\'','fms','bash',4,1,NULL,'2026-01-28 03:41:31','insert_always'),(21,'system.disk.percent_DEPRECATED_21',5,1,30,0,'linux','df -h / | awk \'NR>1\' | xargs | awk \'{print $5}\'','fms','bash',600,1,NULL,'2026-01-28 03:41:31','insert_always'),(22,'system.ram.percent',2,1,30,0,'linux','free | awk \'/Mem:/ {printf 